    "bd": "arepazo",
    "query_solucion": "SELECT CONCAT(c.nombre, ' ', c.apellido) AS Cliente, c.email\nFROM Clientes c\nWHERE EXISTS (\n  SELECT 1\n  FROM Pedidos p\n  WHERE p.cliente_id = c.cliente_id\n  AND p.estado = 'Entregado'\n);",
    "puntos": 35,
