    "bd": "futbol",
    "query_solucion": "SELECT j.nombre, COUNT(*) AS fases_superadas\nFROM Jugadores j\nINNER JOIN Clasificaciones c ON j.id_jugador = c.id_jugador\nWHERE c.superada_bool = TRUE\nGROUP BY j.nombre;",
