    "bd": "futbol",
    "query_solucion": "SELECT j.nombre, SUM(c.ranking_obtenido) AS suma_rankings\nFROM Jugadores j\nINNER JOIN Clasificaciones c ON j.id_jugador = c.id_jugador\nGROUP BY j.nombre;",
