    "bd": "futbol",
    "query_solucion": "SELECT j.nombre, COUNT(*) AS num_clasificaciones\nFROM Jugadores j\nINNER JOIN Clasificaciones c ON j.id_jugador = c.id_jugador\nGROUP BY j.nombre\nHAVING COUNT(*) > 1;",
